/* Russian is the source language; English comes from catalog.json, generated by
   harness/console/kernel/web_catalog.py from the TUI translation tables. */
import { createContext, useCallback, useContext, useEffect, useMemo, useState } from "react";
import type { ReactNode } from "react";
import catalog from "./i18n/catalog.json";
import dsEnglish from "./i18n/ds.en.json";

export type Language = "ru" | "en";
export const LANGUAGES: readonly Language[] = ["ru", "en"];
export const LANGUAGE_KEY = "harness-console-lang";

type Values = Readonly<Record<string, string | number>>;

// The strings of the v3 screens that the kernel tables do not hold yet (see ds.en.json).
const EN: Readonly<Record<string, string>> = { ...catalog.en, ...dsEnglish };
const FACTS: Readonly<Record<string, string>> = catalog.facts;
const TABS: Readonly<Record<string, string>> = catalog.tabs;
const SECTIONS: Readonly<Record<string, Readonly<Record<string, string>>>> = catalog.sections;
// The Russian texts of the cleanup and worktree reasons (kernel/maintenance.py REASONS_RU) and
// the Russian labels of the health check groups (harness/health/render.py GROUP_LABELS_RU).
const REASONS: Readonly<Record<string, string>> = catalog.reasons;
const GROUPS: Readonly<Record<string, string>> = catalog.groups;
// Why each health check matters (kernel/check_rationale.py RATIONALES), by check id.
const RATIONALES: Readonly<Record<string, Readonly<Record<Language, string>>>> = catalog.rationales;
// Check titles (kernel/check_rationale.py TITLES) and state labels (kernel/i18n_strings.py STATE_LABELS).
const TITLES: Readonly<Record<string, Readonly<Record<Language, string>>>> = catalog.titles;
const STATES: Readonly<Record<string, Readonly<Record<Language, string>>>> = catalog.states;

const fill = (text: string, values?: Values): string =>
  values
    ? Object.entries(values).reduce(
        (result, [name, value]) => result.split(`{${name}}`).join(String(value)),
        text,
      )
    : text;

export function translate(language: Language, text: string, values?: Values): string {
  return fill(language === "en" ? (EN[text] ?? text) : text, values);
}

export function sectionLabel(language: Language, key: string): string {
  return SECTIONS[key]?.[language] ?? key;
}

export function factLabel(language: Language, label: string): string {
  return language === "en" ? (FACTS[label] ?? label) : label;
}

/** A page tab label: `Обзор` is a page overview here, folder browsing in the main table. */
export function tabLabel(language: Language, label: string): string {
  return language === "en" ? (TABS[label] ?? translate(language, label)) : label;
}

/** A cleanup or worktree reason as the TUI words it: an empty reason means removable; Russian
    from the server's table, English is the server's own text. */
export function reasonText(language: Language, reason: string): string {
  if (!reason) return translate(language, "Можно удалить");
  return language === "en" ? reason : (REASONS[reason] ?? reason);
}

/** The label of a health check group; an unknown group keeps its id. */
export function groupLabel(language: Language, group: string): string {
  const russian = GROUPS[group];
  return russian === undefined ? group : translate(language, russian);
}

/** Why a health check matters; null for an id the kernel catalog does not describe. */
export function checkRationale(language: Language, id: string): string | null {
  return RATIONALES[id]?.[language] ?? null;
}

/** A ledger, screen or health state in words (kernel i18n_strings.STATE_LABELS); the case of the
    raw value does not matter. An unknown state keeps its value. */
export function stateLabel(language: Language, state: string): string {
  return STATES[state]?.[language] ?? STATES[state.toLowerCase()]?.[language] ?? state;
}

/** The title of a health check (kernel check_rationale.TITLES); an unknown id keeps its id. */
export function checkTitle(language: Language, id: string): string {
  return TITLES[id]?.[language] ?? id;
}

/** `count` with its noun: Russian forms for 1, 2-4 and 5+, English for 1 and the rest. */
export function plural(
  language: Language,
  count: number,
  ru: readonly [string, string, string],
  en: readonly [string, string],
): string {
  if (language === "en") return `${count} ${count === 1 ? en[0] : en[1]}`;
  const tens = count % 100;
  const units = count % 10;
  const form = units === 1 && tens !== 11 ? ru[0] : units >= 2 && units <= 4 && (tens < 12 || tens > 14) ? ru[1] : ru[2];
  return `${count} ${form}`;
}

const isLanguage = (value: unknown): value is Language =>
  typeof value === "string" && (LANGUAGES as readonly string[]).includes(value);

/** The language of "#/...?lang=xx", then the stored choice, then Russian. */
export function initialLanguage(hash: string, stored: string | null): Language {
  const query = hash.includes("?") ? hash.slice(hash.indexOf("?") + 1) : "";
  const fromUrl = new URLSearchParams(query).get("lang");
  if (isLanguage(fromUrl)) return fromUrl;
  return isLanguage(stored) ? stored : "ru";
}

function readStored(): string | null {
  try {
    return localStorage.getItem(LANGUAGE_KEY);
  } catch {
    return null;
  }
}

/** One duration wording for the whole console: `6 дн 1 ч`, `2 ч 7 мин`, `5 мин`, `42 с`. */
export function compactDuration(seconds: number | null | undefined, language: Language): string {
  if (seconds === null || seconds === undefined || Number.isNaN(seconds)) return "—";
  const total = Math.max(0, Math.floor(seconds));
  const [day, hour, minute, second] = language === "ru" ? ["дн", "ч", "мин", "с"] : ["d", "h", "min", "s"];
  const days = Math.floor(total / 86400);
  const hours = Math.floor((total % 86400) / 3600);
  const minutes = Math.floor((total % 3600) / 60);
  if (days) return hours ? `${days} ${day} ${hours} ${hour}` : `${days} ${day}`;
  if (hours) return minutes ? `${hours} ${hour} ${minutes} ${minute}` : `${hours} ${hour}`;
  if (minutes) return `${minutes} ${minute}`;
  return `${total} ${second}`;
}

export interface I18n {
  language: Language;
  setLanguage: (language: Language) => void;
  t: (text: string, values?: Values) => string;
  section: (key: string) => string;
  fact: (label: string) => string;
  tab: (label: string) => string;
  state: (state: string) => string;
  check: (id: string) => string;
  plural: (count: number, ru: readonly [string, string, string], en: readonly [string, string]) => string;
  /** `compactDuration` in the current language. */
  duration: (seconds: number | null | undefined) => string;
}

const I18nContext = createContext<I18n | null>(null);

export function LanguageProvider({ children }: { children: ReactNode }) {
  const [language, setState] = useState<Language>(() =>
    initialLanguage(window.location.hash, readStored()),
  );
  useEffect(() => {
    document.documentElement.lang = language;
  }, [language]);
  const setLanguage = useCallback((next: Language) => {
    setState(next);
    try {
      localStorage.setItem(LANGUAGE_KEY, next);
    } catch {
      /* Storage is optional. */
    }
  }, []);
  const value = useMemo<I18n>(
    () => ({
      language,
      setLanguage,
      t: (text, values) => translate(language, text, values),
      section: (key) => sectionLabel(language, key),
      fact: (label) => factLabel(language, label),
      tab: (label) => tabLabel(language, label),
      state: (state) => stateLabel(language, state),
      check: (id) => checkTitle(language, id),
      plural: (count, ru, en) => plural(language, count, ru, en),
      duration: (seconds) => compactDuration(seconds, language),
    }),
    [language, setLanguage],
  );
  return <I18nContext.Provider value={value}>{children}</I18nContext.Provider>;
}

export function useI18n(): I18n {
  const value = useContext(I18nContext);
  if (!value) throw new Error("useI18n outside LanguageProvider");
  return value;
}
